 public static void Build(){EditorSceneManager.OpenScene("Assets/Scenes/Island_Blockout_V01.unity");t=Object.FindFirstObjectByType<Terrain>();td=Object.Instantiate(t.terrainData);AssetDatabase.CreateAsset(td,D+"/SurfaceTerrain.asset");t.terrainData=td;t.GetComponent<TerrainCollider>().terrainData=td;
 string[] ids={"coast_sand_01","coast_sand_01","grass_path_2","forest_ground_04","brown_mud_leaves_01","rocky_terrain_02"};string[] names={"DrySand","WetSand","Grass","SoilGravel","LeafSoil","Rock"};var layers=new TerrainLayer[6];
 for(int i=0;i<6;i++){string p=D+"/Textures/"+ids[i]+"_diff.jpg",n=D+"/Textures/"+ids[i]+"_nor_gl.jpg";var imp=(TextureImporter)AssetImporter.GetAtPath(p);imp.wrapMode=TextureWrapMode.Repeat;imp.SaveAndReimport();var ni=(TextureImporter)AssetImporter.GetAtPath(n);ni.textureType=TextureImporterType.NormalMap;ni.wrapMode=TextureWrapMode.Repeat;ni.SaveAndReimport();layers[i]=new TerrainLayer{diffuseTexture=AssetDatabase.LoadAssetAtPath<Texture2D>(p),normalMapTexture=AssetDatabase.LoadAssetAtPath<Texture2D>(n),tileSize=new Vector2(i==5?7:4,i==5?7:4),normalScale=.45f,metallic=0,smoothness=i==1?.3f:.05f};AssetDatabase.CreateAsset(layers[i],D+"/"+names[i]+".terrainlayer");}td.terrainLayers=layers;
 // Only inset the existing river corridor; all coastline heights remain identical.
 var heights=td.GetHeights(0,0,513,513);var original=(float[,])heights.Clone();float[] water=new float[141];for(int i=0;i<=140;i++){float z=-235+2*i;water[i]=Mathf.Max(.05f,Y(RX(z),z)-.6f);if(i>0)water[i]=Mathf.Max(water[i],water[i-1]+.006f);}
 for(int z=0;z<513;z++)for(int x=0;x<513;x++){float xx=x/512f*720-360,zz=z/512f*720-360,d=Mathf.Abs(xx-RX(zz)),h=heights[z,x]*180-25;if(zz< -235||zz>45||h<1||d>12)continue;float level=water[Mathf.Clamp(Mathf.RoundToInt((zz+235)/2),0,140)];float bed=level-1.7f;heights[z,x]=(Mathf.Lerp(bed,h,S(4,12,d))+25)/180;}td.SetHeights(0,0,heights);
 td.alphamapResolution=512;var alpha=new float[512,512,6];for(int z=0;z<512;z++)for(int x=0;x<512;x++){float xx=x/511f*720-360,zz=z/511f*720-360,h=Y(xx,zz),noise=Mathf.PerlinNoise(xx*.035f+20,zz*.035f+20),slope=td.GetSteepness(x/511f,z/511f);float beach=1-S(4,13,h+noise*4),wet=1-S(.4f,2.6f,h),rock=Mathf.Max(S(25,48,slope),S(40,80,h))*.85f,river=(1-S(5,17,Mathf.Abs(xx-RX(zz))))*S(-240,-225,zz)*(1-S(40,50,zz));float[] w={beach*(1-wet),beach*wet,(1-beach)*(1-rock)*(.65f+.25f*noise)*(1-river),.1f+river*.9f,(1-beach)*(1-rock)*(.18f+noise*.25f),rock+river*.15f};float sum=0;foreach(float a in w)sum+=a;for(int i=0;i<6;i++)alpha[z,x,i]=w[i]/sum;}td.SetAlphamaps(0,0,alpha);
 var mat=new Material(Shader.Find("Nature/Terrain/Standard"));AssetDatabase.CreateAsset(mat,D+"/Terrain.mat");t.materialTemplate=mat;t.Flush();var old=GameObject.Find("River valley reservation");if(old)old.SetActive(false);
 var mesh=new Mesh();var vertices=new List<Vector3>();var tris=new List<int>();for(int i=0;i<=140;i++){float z=-235+i*2;vertices.Add(new Vector3(RX(z)-3.5f,water[i],z));vertices.Add(new Vector3(RX(z)+3.5f,water[i],z));if(i<140){int k=i*2;tris.AddRange(new[]{k,k+2,k+1,k+1,k+2,k+3});}}mesh.SetVertices(vertices);mesh.SetTriangles(tris,0);mesh.RecalculateNormals();AssetDatabase.CreateAsset(mesh,D+"/River.mesh");var go=new GameObject("River water above sculpted bed");go.AddComponent<MeshFilter>().sharedMesh=mesh;var wm=new Material(Shader.Find("Standard"));wm.color=new Color(.15f,.55f,.58f);wm.SetFloat("_Glossiness",.65f);AssetDatabase.CreateAsset(wm,D+"/Water.mat");go.AddComponent<MeshRenderer>().sharedMaterial=wm;
 Directory.CreateDirectory("Docs/Island_Surface_V02");var cam=GameObject.Find("Overview angled").GetComponent<Camera>();foreach(var line in Object.FindObjectsByType<LineRenderer>(FindObjectsSortMode.None))line.enabled=false;foreach(var text in Object.FindObjectsByType<TextMesh>(FindObjectsSortMode.None))text.gameObject.SetActive(false);
 cam.orthographic=true;cam.orthographicSize=320;cam.transform.position=new(0,1000,0);cam.transform.rotation=Quaternion.Euler(90,0,0);Shot(cam,"01_Top");Close(cam,"02_Beach",-190,-165);Close(cam,"03_Forest",-100,-25);Close(cam,"04_River",RX(-90),-90);Close(cam,"05_Mountain",-15,105);Close(cam,"06_Transition",-170,-130);
 cam.orthographic=true;cam.orthographicSize=340;cam.transform.position=new(650,700,-820);cam.transform.LookAt(new Vector3(0,15,0));Shot(cam,"00_Overview");EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene(),"Assets/Scenes/Island_Surface_V02.unity");AssetDatabase.SaveAssets();Debug.Log("SURFACE_V02_COMPLETE");}
 static void Close(Camera c,string name,float x,float z){c.orthographic=false;c.fieldOfView=58;c.transform.position=new Vector3(x+13,Y(x,z)+11,z-17);c.transform.LookAt(new Vector3(x,Y(x,z),z));Shot(c,name);}
 static void Shot(Camera c,string name){var r=new RenderTexture(1600,1100,24);c.targetTexture=r;c.Render();RenderTexture.active=r;var tex=new Texture2D(1600,1100,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1600,1100),0,0);tex.Apply();File.WriteAllBytes("Docs/Island_Surface_V02/"+name+".png",tex.EncodeToPNG());c.targetTexture=null;RenderTexture.active=null;Object.DestroyImmediate(tex);Object.DestroyImmediate(r);}
}
